import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");

      const cleanData = res.data.filter(d => d.waktu !== "None");

      setData(cleanData);
      setLoading(false);
    } catch (err) {
      console.log(err);
    }
  };

  const latest = data.length > 0 ? data[0] : null;

  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e",
        tension: 0.4
      }
    ]
  };

  const getStatusColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN") return "#ef4444";
    if (kondisi === "PERINGATAN") return "#f97316";
    if (kondisi === "NORMAL") return "#22c55e";
    return "#22c55e";
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", background: "#0f172a", color: "white" }}>

      {/* SIDEBAR */}
      <div style={{
        width: 230,
        background: "#1e293b",
        padding: 20
      }}>
        <h2 style={{ marginBottom: 30 }}>⚡ Hematrik</h2>

        <p onClick={() => setPage("dashboard")} style={{ cursor: "pointer", margin: 10 }}>Dashboard</p>
        <p onClick={() => setPage("monitoring")} style={{ cursor: "pointer", margin: 10 }}>Monitoring</p>
        <p onClick={() => setPage("history")} style={{ cursor: "pointer", margin: 10 }}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 30 }}>

        {loading && <h2>Loading data...</h2>}

        {/* ================= DASHBOARD ================= */}
        {!loading && page === "dashboard" && latest && (
          <>
            <h1 style={{ marginBottom: 20 }}>📊 Dashboard Monitoring</h1>

            {/* STATUS BAR */}
            <div style={{
              padding: 15,
              borderRadius: 10,
              background: getStatusColor(latest.kondisi),
              marginBottom: 25
            }}>
              {latest.notifikasi}
            </div>

            {/* CARDS */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gap: 20
            }}>

              <div style={cardStyle}>
                <h4>👤 People</h4>
                <h1>{latest.jumlah_orang}</h1>
              </div>

              <div style={cardStyle}>
                <h4>💡 Listrik</h4>
                <h1>{latest.status_listrik}</h1>
              </div>

              <div style={cardStyle}>
                <h4>⚠️ Kondisi</h4>
                <h1 style={{ color: getStatusColor(latest.kondisi) }}>
                  {latest.kondisi}
                </h1>
              </div>
            </div>

            {/* CHART */}
            <div style={{
              marginTop: 30,
              background: "#1e293b",
              padding: 20,
              borderRadius: 15
            }}>
              <h3>📈 Grafik Orang</h3>
              <Line data={chartData} />
            </div>
          </>
        )}

        {/* ================= MONITORING ================= */}
        {!loading && page === "monitoring" && latest && (
          <>
            <h1>📷 Monitoring</h1>

            <div style={{
              background: "#1e293b",
              padding: 20,
              borderRadius: 15
            }}>
              <img
                src={`http://127.0.0.1:8000/${latest.gambar}`}
                width="400"
                style={{ borderRadius: 10 }}
                alt=""
              />
            </div>

            <h2 style={{ marginTop: 20 }}>
              {latest.jumlah_orang} Orang Terdeteksi
            </h2>

            <h3 style={{ color: getStatusColor(latest.kondisi) }}>
              {latest.kondisi}
            </h3>
          </>
        )}

        {/* ================= HISTORY ================= */}
        {!loading && page === "history" && (
          <>
            <h1>📜 History</h1>

            <table style={{
              width: "100%",
              marginTop: 20,
              borderCollapse: "collapse"
            }}>
              <thead>
                <tr style={{ background: "#1e293b" }}>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>

              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getStatusColor(d.kondisi) }}>
                      {d.kondisi}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

const cardStyle = {
  background: "#1e293b",
  padding: 20,
  borderRadius: 15,
  boxShadow: "0 5px 15px rgba(0,0,0,0.3)"
};

export default App;
